#!/usr/bin/env python3
"""Independently review all authored native, wire and retired child states."""
import argparse,hashlib,importlib.util,json,math,pathlib
p=pathlib.Path(__file__).with_name('review-sync-mutation-common.py');spec=importlib.util.spec_from_file_location('mutation_fanout_guard',p);g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g)
need=g.need;encode=g.encode
COLUMNS='id,routine_id,revision,scheduled_at,started,finished,trigger,status,chat_id,message,scope'
def review(root,profile):
 root=pathlib.Path(root).absolute();profile=pathlib.Path(profile).absolute();build,run=g.dataset(root,profile,'fanout');need((root/'owned-fixture').read_bytes()==b'OSwind authored sync mutation fanout v1','Owned marker differs');reports=json.loads((root/'report.json').read_text());need([r['count'] for r in reports]==[1000,10000],'Fanout coverage differs');pins={};results=[]
 for report in reports:
  n=report['count'];folder=root/('n%d'%n);need(json.loads((folder/'report.json').read_text())==report and report['librarySchema']==31,'Per-size report differs');need(report['announcements']==n and report['beforeSequence']==n and report['finalSequence']==2*n,'Announcement/sequence coverage differs');need(report['testBundle']==str(profile/'payload/OSwindPackageTests.xctest'),'Executed bundle differs')
  for k in ['loadSeconds','outgoingPreparationSeconds','deletionSeconds']:need(type(report[k]) in [int,float] and math.isfinite(report[k]) and report[k]>=0,'Nonfinite timer')
  with g.database(folder/'before-delete.sqlite',pins) as before,g.database(folder/'receiver/memory.sqlite',pins) as after,g.database(folder/'producer/memory.sqlite',pins) as producer:
   lookup=g.identity_lookup_plan(before,profile)
   g.identity_lookup_plan(after,profile);g.identity_lookup_plan(producer,profile)
   native=before.execute('SELECT '+COLUMNS+' FROM routine_runs ORDER BY id').fetchall();need(len(native)==n,'Native pre-delete coverage differs');expected={};own=before.execute('SELECT replica,sequence FROM personal_sync_local').fetchone();need(own is not None and own[1]==n,'Before local sequence differs');parent=before.execute('SELECT id,revision,enabled,payload FROM routines').fetchall();need(len(parent)==1 and parent[0][1:3]==(1,0) and json.loads(parent[0][3])['prompt']=='Owned fanout prompt','Paused native recipe differs');parent_id=parent[0][0]
   puts={}
   for sequence,raw in before.execute('SELECT sequence,revision FROM personal_sync_outbox ORDER BY sequence'):
    r=json.loads(raw);need(r['dot']==dict(replica=own[0],counter=sequence) and r['mutation']=='put' and r['key']['kind']=='routineRun','Before run publication differs');puts[r['key']['digest']]=r
   need(len(puts)==n,'Distinct authored put coverage differs')
   for index,row in enumerate(native,1):
    local=row[0];need(local=='fanout-%08d'%index and row[1]==parent_id and row[2:9]==(1,1700000000+index,1700000000+index,1700000001+index,'manual','failed',None) and row[9]=='Owned fanout run %d'%index,'Authored native run differs')
    frame=g.frames.frame([local]);identity=before.execute('SELECT object_digest,origin,lifetime,local_key,deleted FROM personal_sync_identities WHERE table_name=? AND key_frame=?',('routine_runs',frame)).fetchone();need(identity is not None and identity[3:]==(hashlib.sha256(frame).digest(),0),'Native/global mapping differs');digest,origin,lifetime=identity[:3];wire=before.execute('SELECT v.body,p.content_sha,p.row_digest FROM personal_sync_version_projection p JOIN personal_sync_versions v ON v.object_digest=p.object_digest AND v.content_sha=p.content_sha WHERE p.object_digest=?',(digest,)).fetchall();need(len(wire)==1,'Current packet absent');raw,content,native_sha=wire[0];packet=json.loads(raw);ident=dict(table='routine_runs',origin=origin,lifetime=lifetime);need(packet['identity']==ident and g.key('routineRun',ident)==digest and encode(packet)==raw and g.m.digest(raw)==content and g.m.digest(g.frames.frame(row))==native_sha,'Actual packet/native frame differs');body=packet['body']['routineRun']['_0'];need(body['message']==row[9] and body['status']=='failed' and body['trigger']=='manual' and body['scheduledAt']+978307200==row[3] and body['started']+978307200==row[4] and body['finished']+978307200==row[5] and g.m.strict(body['filter'],json.loads(row[10])),'Wire fields differ from authored native source');need(puts[digest]['content']==dict(bytes=len(raw),sha256=content),'Actual initial journal content differs');expected[digest]=(identity,puts[digest])
   need(before.execute('SELECT count(*) FROM personal_sync_changes').fetchone()==(0,) and before.execute('SELECT count(*) FROM personal_sync_pending').fetchone()==(0,),'Before capture/pending differs')
   root_op=report['root'];producer_ops=producer.execute('SELECT sequence,revision FROM personal_sync_outbox ORDER BY sequence').fetchall();need(len(producer_ops)==2 and json.loads(producer_ops[-1][1])==root_op and root_op['mutation']=='delete' and root_op['key']['kind']=='routine','Actual parent deletion differs');root_key=root_op['key'];root_dot=root_op['dot'];initial=json.loads(producer_ops[0][1]);need(initial['key']==root_key and initial['mutation']=='put','Actual parent put differs')
   for table in ['routines','routine_runs','routine_run_originals','personal_sync_versions','personal_sync_version_runs','personal_sync_version_recipes','personal_sync_version_sessions','personal_sync_changes','personal_sync_pending']:need(after.execute('SELECT count(*) FROM '+table).fetchone()==(0,),'Post-delete residue in '+table)
   need(after.execute('SELECT used_bytes FROM personal_sync_version_state').fetchone()==(0,),'Cache accounting not empty');need(after.execute('SELECT sequence FROM personal_sync_local').fetchone()==(2*n,),'Final sequence differs');announced={}
   for sequence,raw in after.execute('SELECT sequence,revision FROM personal_sync_outbox ORDER BY sequence'):
    r=json.loads(raw)
    if sequence<=n:need(r==puts[r['key']['digest']],'Original outbox prefix changed');continue
    digest=r['key']['digest'];need(digest in expected and digest not in announced and r['key']['kind']=='routineRun' and r['mutation']=='delete' and r.get('content') is None and r['dot']==dict(replica=own[0],counter=sequence),'Derived announcement differs');need(r['context'].get(root_dot['replica'],0)>=root_dot['counter'] and r['context'].get(own[0],0)==sequence-1,'Root or local causal frontier missing');announced[digest]=r
   need(set(announced)==set(expected),'Exact derived-key membership differs')
   for digest,(identity,put) in expected.items():
    mapped=after.execute('SELECT origin,lifetime,local_key,key_frame,deleted FROM personal_sync_identities WHERE object_digest=?',(digest,)).fetchone();need(mapped==(identity[1],identity[2],identity[3],None,1),'Retired lifetime metadata differs');state=after.execute("SELECT state FROM personal_sync_registers WHERE kind='routineRun' AND digest=?",(digest,)).fetchone();need(state is not None,'Child barrier absent');state=json.loads(state[0]);need(state['heads']==[] and state['deletions'].get(own[0],0)==announced[digest]['dot']['counter'],'Child register not retired');need(after.execute('SELECT count(*) FROM personal_sync_version_revoked WHERE object_digest=?',(digest,)).fetchone()==(1,),'Child cache barrier absent')
   parent_state=json.loads(after.execute('SELECT state FROM personal_sync_registers WHERE kind=? AND digest=?',(root_key['kind'],root_key['digest'])).fetchone()[0]);need(parent_state['heads']==[] and parent_state['deletions'].get(root_dot['replica'],0)==root_dot['counter'],'Parent barrier differs')
  results.append(dict(count=n,deletionSeconds=report['deletionSeconds'],exactNativeSources=n,exactChildBarriers=n,rootCausalityVerified=True,identityLookup=lookup))
 return dict(state='passed',results=results,unchangedSQLiteFiles=pins,scope='Owned warm metadata component, exact native/wire/global retirement. No media/model/transport/physical-power or ranking claim.')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('root',type=pathlib.Path);p.add_argument('profile',type=pathlib.Path);a=p.parse_args();print(json.dumps(review(a.root,a.profile),indent=2))
